pub fn solve(input: &str) -> String {
    // Return the first index whose reading is negative, or -1 when none is negative.
    // Parse the visible input into the structures your algorithm needs.
    // Whitespace surrounding the complete input is insignificant.
    let _ = input;
    todo!("implement Linear Scan")
}

challenge.verificationSource:
mod solution;

fn main() {
    let cases = [
    (r#"[4, 9, -2, 7]"#, r#"2"#),
    (r#"[1, 2, 3]"#, r#"-1"#),
    (r#"
[1, 2, 3]
"#, r#"-1"#),
    (r#"  
[4, 9, -2, 7]
  "#, r#"2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS linear-scan");
}

