challenge.verificationSource:
mod solution;

fn main() {
    let cases = [
    (r#"[3,9,20,null,null,15,7]"#, r#"true"#),
    (r#"[1,2,null,3]"#, r#"false"#),
    (r#"
[1,2,null,3]
"#, r#"false"#),
    (r#"  
[3,9,20,null,null,15,7]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS tree-height-balance");
}

