            let color = if sun {
                4
            } else if y < 5 {
                1
            } else if y < 9 {
                2
            } else if x.abs_diff(17) < 3 {
                4
            } else if (x + y) % 4 == 0 {
                5
            } else {
                3
            };
            pixels.push(HEX[color] as char);
        }
    }

    println!(
        r##"CRABRIX_CANVAS:{{"title":"Pixel Sunset","width":24,"height":16,"palette":["#111827","#312E81","#F97316","#0F766E","#FDE68A","#22D3EE"],"pixels":"{}"}}"##,
        pixels
    );
    println!("Edit the coordinates, then Run again.");
}

const W: usize = 24;
const H: usize = 16;

fn neighbors(grid: &[bool], x: usize, y: usize) -> u8 {
    let mut total = 0;
    for dy in [-1_i32, 0, 1] {
        for dx in [-1_i32, 0, 1] {
            if dx == 0 && dy == 0 { continue; }
            let nx = x as i32 + dx;
            let ny = y as i32 + dy;
            if nx >= 0 && ny >= 0
                && nx < W as i32 && ny < H as i32
                && grid[ny as usize * W + nx as usize]
            {
                total += 1;
            }
        }
    }
    total
}

fn main() {
    let mut grid = vec![false; W * H];
    for (x, y) in [
        (4, 5), (5, 6), (3, 7), (4, 7), (5, 7),
        (14, 4), (15, 4), (16, 4), (16, 5),
    ] {
        grid[y * W + x] = true;
    }

    let mut next = vec![false; W * H];
    for y in 0..H {
        for x in 0..W {
            let count = neighbors(&grid, x, y);
            next[y * W + x] = count == 3
                || (grid[y * W + x] && count == 2);
        }
    }
    let pixels: String = next.iter()
        .map(|alive| if *alive { '2' } else { '0' })
        .collect();
    println!(
        r##"CRABRIX_CANVAS:{{"title":"Cellular Garden","width":24,"height":16,"palette":["#071A13","#166534","#4ADE80"],"pixels":"{}"}}"##,
        pixels
    );
    println!("One generation evolved locally.");
}

const HEX: &[u8] = b"0123456789abcdef";

fn main() {
    let width = 32;
    let height = 20;
    let mut pixels = String::new();

    for py in 0..height {
        for px in 0..width {
            let cx = px as f64 / width as f64 * 3.2 - 2.2;
            let cy = py as f64 / height as f64 * 2.2 - 1.1;
            let (mut x, mut y, mut step) = (0.0, 0.0, 0);
            while x * x + y * y <= 4.0 && step < 30 {
                let next_x = x * x - y * y + cx;
                y = 2.0 * x * y + cy;
                x = next_x;
                step += 1;
            }
            let color = if step == 30 { 0 } else {
                1 + step * 5 / 30
            };
            pixels.push(HEX[color] as char);
        }
    }
    println!(
        r##"CRABRIX_CANVAS:{{"title":"Mandelbrot Canvas","width":32,"height":20,"palette":["#020617","#1E1B4B","#4338CA","#7C3AED","#EC4899","#FDE047"],"pixels":"{}"}}"##,
        pixels
    );
    println!("640 points iterated with real Rust.");
}

const W: usize = 24;
